  const top = ordered[0];
  if (tallies[top] >= threshold || ordered.length === 1) return {
    candidates,
    rules,
    rounds,
    winner: top,
    totalBallots
  };
  if (ordered.length === 2 && tallies[ordered[0]] > tallies[ordered[1]]) return {
    candidates,
    rules,
    rounds,
    winner: top,
    totalBallots
  };
  // choose who to eliminate
  let elim: string[] = [];
  if (rules.batch) {
    const asc = [...ordered].reverse();
    let sum = 0;
    for (let k = 1; k <= asc.length - 2; k++) {
      sum += tallies[asc[k - 1]];
      if (sum < tallies[asc[k]]) elim = asc.slice(0, k);
    }
  }
  if (elim.length === 0) {
    const min = Math.min(...Object.values(tallies));
    let tied = Object.keys(tallies).filter(c => tallies[c] === min);
    if (tied.length > 1 && rules.tiebreak === 'previous-round') {
      for (let back = rounds.length - 2; back >= 0 && tied.length > 1; back--) {
        const t = rounds[back].tallies;
        const m = Math.min(...tied.map(c => t[c]));
        tied = tied.filter(c => t[c] === m);
      }
      if (tied.length === 1) round.tieNote = 'previous-round';
    }
    if (tied.length > 1) {
      tied.sort((a, b) => lot.indexOf(b) - lot.indexOf(a));
      tied = [tied[0]];
      round.tieNote = 'lot';
    }
    elim = tied;
  }
  round.eliminated = elim;
  for (const c of elim) continuing.delete(c);
}

